    "task": "Clean selected. A stable Catalog domain port belongs to one catalog context; it returns framework-free values, with no cross-context work, ordered side effects, or added business failure semantics. Its existing adapters normalize expected failures to unavailable and honor the supplied cooperative cancellation predicate, so cleanup stops obsolete work. No auth/common-error code is part of this port. The new client hook and view show not-ready/loading/empty/success/error, map the title value into render state, and handle an unexpected rejected promise without exposing its object. Review whether the hook may consume this one repository interface directly rather than introducing a forwarding use case. The app composition passes the same Catalog instance while mounted.",
    "files": {
      "presentation/CatalogState.ts": "import { useEffect, useState } from \"react\";\nimport { Catalog, CatalogResult } from \"../domain/Catalog\";\n\ntype RequestState =\n  | Readonly<{ phase: \"not-ready\" | \"loading\" | \"failed\" }>\n  | Readonly<{ phase: \"settled\"; result: CatalogResult }>;\nexport type CatalogUiState =\n  | Readonly<{ status: \"not-ready\" | \"loading\" | \"empty\" }>\n  | Readonly<{ status: \"success\"; title: string }>\n  | Readonly<{ status: \"error\"; message: string }>;\n\nfunction toCatalogUiState(request: RequestState): CatalogUiState {\n  switch (request.phase) {\n    case \"not-ready\": return { status: \"not-ready\" };\n    case \"loading\": return { status: \"loading\" };\n    case \"failed\": return { status: \"error\", message: \"Unable to load catalog.\" };\n    case \"settled\":\n      switch (request.result.kind) {\n        case \"success\": return { status: \"success\", title: request.result.title.text };\n        case \"empty\": return { status: \"empty\" };\n        case \"unavailable\": return { status: \"error\", message: \"Catalog unavailable.\" };\n      }\n  }\n}\n\nexport function useCatalogState(catalog: Catalog): CatalogUiState {\n  const [requestState, setRequestState] = useState<RequestState>({ phase: \"not-ready\" });\n  useEffect(() => {\n    let cancelled = false;\n    setRequestState({ phase: \"loading\" });\n    void catalog.title({ isCancelled: () => cancelled }).then(result => {\n      if (!cancelled) setRequestState({ phase: \"settled\", result });\n    }).catch(() => {\n      if (!cancelled) setRequestState({ phase: \"failed\" });\n    });\n    return () => { cancelled = true; };\n  }, [catalog]);\n  return toCatalogUiState(requestState);\n}\n",
      "presentation/CatalogScreen.tsx": "import { Catalog } from \"../domain/Catalog\";\nimport { CatalogUiState, useCatalogState } from \"./CatalogState\";\n\nexport function CatalogScreen({ catalog }: { catalog: Catalog }) {\n  return <CatalogView uiState={useCatalogState(catalog)} />;\n}\nfunction CatalogView({ uiState }: { uiState: CatalogUiState }) {\n  switch (uiState.status) {\n    case \"not-ready\": return <p>Catalog not loaded.</p>;\n    case \"loading\": return <p role=\"status\">Loading catalog.</p>;\n    case \"empty\": return <p>No catalog available.</p>;\n    case \"error\": return <p role=\"alert\">{uiState.message}</p>;\n    case \"success\": return <h1>{uiState.title}</h1>;\n  }\n}\n",
