    "task": "Clean selected. The existing operation hook below owns observable UI state, duplicate-click prevention, cooperative unmount cancellation and local failure rendering; its renderer consumes uiState and checkout. The proposed useCheckoutState callback directly sequences separate Inventory and Payments domain contexts. Their adapter methods preserve normalized failure/cancellation contracts, but successful stock reservation followed by failed payment requires business compensation that is not owned by either individual port. Review the placement of that cross-context orchestration, not the already established hook state mechanics.",
    "files": {
      "presentation/CheckoutState.ts": "import { Inventory, Payments } from \"../domain/CheckoutPorts\";\nimport { useCheckoutOperation } from \"./operation\";\nexport function useCheckoutState(stock: Inventory, payments: Payments) {\n  return useCheckoutOperation(async cancellation => {\n    await stock.reserve(cancellation);\n    await payments.charge(cancellation);\n  });\n}\n",
      "presentation/operation.ts": "import { useCallback, useEffect, useRef, useState } from \"react\";\nimport { Cancellation } from \"../domain/CheckoutPorts\";\ntype UiState = Readonly<{ status: \"ready\" | \"working\" | \"success\" }> | Readonly<{ status: \"error\"; message: string }>;\nexport function useCheckoutOperation(operation: (cancellation: Cancellation) => Promise<void>) {\n  const [uiState, setUiState] = useState<UiState>({ status: \"ready\" });\n  const active = useRef<{ cancelled: boolean } | null>(null);\n  useEffect(() => () => { if (active.current) active.current.cancelled = true; }, []);\n  const checkout = useCallback(async () => {\n    if (active.current) return;\n    const request = { cancelled: false };\n    active.current = request;\n    setUiState({ status: \"working\" });\n    try {\n      await operation({ isCancelled: () => request.cancelled });\n      if (!request.cancelled) setUiState({ status: \"success\" });\n    } catch {\n      if (!request.cancelled) setUiState({ status: \"error\", message: \"Checkout failed.\" });\n    } finally {\n      if (active.current === request) active.current = null;\n    }\n  }, [operation]);\n  return { uiState, checkout };\n}\n",
      "domain/CheckoutPorts.ts": "export type Cancellation = Readonly<{ isCancelled(): boolean }>;\nexport interface Inventory { reserve(cancellation: Cancellation): Promise<void> }\nexport interface Payments { charge(cancellation: Cancellation): Promise<void> }\n"
